macro_rules! deps {
    () => {
        TimeDelta!();
        DateTime!();
        Error!();
        NaiveDate!();
    };
}

macro_rules! DurationRound {
    () => {
        deps!();
        # [doc = " Extension trait for rounding or truncating a DateTime by a TimeDelta."] # [doc = ""] # [doc = " # Limitations"] # [doc = " Both rounding and truncating are done via [`TimeDelta::num_nanoseconds`] and"] # [doc = " [`DateTime::timestamp_nanos_opt`]. This means that they will fail if either the"] # [doc = " `TimeDelta` or the `DateTime` are too big to represented as nanoseconds. They"] # [doc = " will also fail if the `TimeDelta` is bigger than the timestamp, negative or zero."] pub trait DurationRound : Sized { # [doc = " Error that can occur in rounding or truncating"] # [cfg (feature = "std")] type Err : std :: error :: Error ; # [doc = " Error that can occur in rounding or truncating"] # [cfg (all (not (feature = "std") , feature = "core-error"))] type Err : core :: error :: Error ; # [doc = " Error that can occur in rounding or truncating"] # [cfg (all (not (feature = "std") , not (feature = "core-error")))] type Err : fmt :: Debug + fmt :: Display ; # [doc = " Return a copy rounded by TimeDelta."] # [doc = ""] # [doc = " # Example"] # [doc = " ``` rust"] # [doc = " # use chrono::{DurationRound, TimeDelta, NaiveDate};"] # [doc = " let dt = NaiveDate::from_ymd_opt(2018, 1, 11)"] # [doc = "     .unwrap()"] # [doc = "     .and_hms_milli_opt(12, 0, 0, 154)"] # [doc = "     .unwrap()"] # [doc = "     .and_utc();"] # [doc = " assert_eq!("] # [doc = "     dt.duration_round(TimeDelta::try_milliseconds(10).unwrap()).unwrap().to_string(),"] # [doc = "     \"2018-01-11 12:00:00.150 UTC\""] # [doc = " );"] # [doc = " assert_eq!("] # [doc = "     dt.duration_round(TimeDelta::try_days(1).unwrap()).unwrap().to_string(),"] # [doc = "     \"2018-01-12 00:00:00 UTC\""] # [doc = " );"] # [doc = " ```"] fn duration_round (self , duration : TimeDelta) -> Result < Self , Self :: Err > ; # [doc = " Return a copy truncated by TimeDelta."] # [doc = ""] # [doc = " # Example"] # [doc = " ``` rust"] # [doc = " # use chrono::{DurationRound, TimeDelta, NaiveDate};"] # [doc = " let dt = NaiveDate::from_ymd_opt(2018, 1, 11)"] # [doc = "     .unwrap()"] # [doc = "     .and_hms_milli_opt(12, 0, 0, 154)"] # [doc = "     .unwrap()"] # [doc = "     .and_utc();"] # [doc = " assert_eq!("] # [doc = "     dt.duration_trunc(TimeDelta::try_milliseconds(10).unwrap()).unwrap().to_string(),"] # [doc = "     \"2018-01-11 12:00:00.150 UTC\""] # [doc = " );"] # [doc = " assert_eq!("] # [doc = "     dt.duration_trunc(TimeDelta::try_days(1).unwrap()).unwrap().to_string(),"] # [doc = "     \"2018-01-11 00:00:00 UTC\""] # [doc = " );"] # [doc = " ```"] fn duration_trunc (self , duration : TimeDelta) -> Result < Self , Self :: Err > ; # [doc = " Return a copy rounded **up** by TimeDelta."] # [doc = ""] # [doc = " # Example"] # [doc = " ``` rust"] # [doc = " # use chrono::{DurationRound, TimeDelta, NaiveDate};"] # [doc = " let dt = NaiveDate::from_ymd_opt(2018, 1, 11)"] # [doc = "     .unwrap()"] # [doc = "     .and_hms_milli_opt(12, 0, 0, 154)"] # [doc = "     .unwrap()"] # [doc = "     .and_utc();"] # [doc = " assert_eq!("] # [doc = "     dt.duration_round_up(TimeDelta::milliseconds(10)).unwrap().to_string(),"] # [doc = "     \"2018-01-11 12:00:00.160 UTC\""] # [doc = " );"] # [doc = " assert_eq!("] # [doc = "     dt.duration_round_up(TimeDelta::hours(1)).unwrap().to_string(),"] # [doc = "     \"2018-01-11 13:00:00 UTC\""] # [doc = " );"] # [doc = ""] # [doc = " assert_eq!("] # [doc = "     dt.duration_round_up(TimeDelta::days(1)).unwrap().to_string(),"] # [doc = "     \"2018-01-12 00:00:00 UTC\""] # [doc = " );"] # [doc = " ```"] fn duration_round_up (self , duration : TimeDelta) -> Result < Self , Self :: Err > ; }
    };
}

DurationRound!()